/**
 * require-spec-link — every `it()`/`test()` must be linked to a spec or ADR.
 *
 * The spec-traceability convention authors the link INSIDE the spec.md/adr `.md`
 * as an inline trailing parenthetical — `Statement. ([validated by](test.ts#L42))`.
 * This rule inverts that view: it goes over each test declaration and fails the
 * ones that no spec or ADR statement references, so tests cannot silently drift
 * out of spec coverage.
 *
 * A test is linked when the spec/adr corpus carries a `([validated by](this#Lnn))`
 * link whose line falls inside the test's line span, or a whole-file link (no
 * `#L`) to the file. The corpus is read once per process (memoized per specsRoot)
 * via the shared parser — see `lib/spec-link-index.mjs`. Type info is off for
 * test files, so this works from the ESTree AST + filename + filesystem only.
 *
 * Detect-only: writing the link needs a human to pick which statement the test
 * validates, not a codemod.
 */
import path from "node:path";
import { isTestFile } from "./lib/spec-parsers.mjs";
import { buildLinkIndex, corpusExists, readSpecFiles, toPosix, } from "./lib/spec-link-index.mjs";
/**
 * specsRoot+roots → index, so the corpus is walked once per process.
 *
 * Note: the cache is keyed on specsRoot only, with no mtime/content hash — a
 * single-pass `eslint`/CI run always reads fresh, but a long-lived ESLint
 * server (VS Code extension, --watch) will not see a spec link added after the
 * first lint until the server restarts.
 */
const indexCache = new Map();
/** specsRoots we've already warned about having no spec/adr corpus, so a
 * misconfigured run warns once instead of once per linted test file.
 *
 * Scope is the whole Node process, matching `indexCache` above. In a one-shot
 * `eslint`/CI run that is exactly one warning. In a long-lived ESLint server
 * (VS Code, --watch) the module is not re-required between cycles, so once a
 * specsRoot has warned it stays quiet even after the CWD is fixed — the same
 * process-lifetime memoization caveat the corpus cache carries. Restart the
 * server (or the editor) to re-arm the warning. */
const warnedMissingCorpus = new Set();
function getIndex(specsRoot, roots) {
    // `\0` separates every element so no root value can collide with the joiner.
    const key = [specsRoot, ...roots].join("\0");
    let index = indexCache.get(key);
    if (!index) {
        index = buildLinkIndex(readSpecFiles(specsRoot, roots));
        indexCache.set(key, index);
    }
    return index;
}
/** The base identifier of a (possibly chained) callee — `it` in `it.each([])(…)`. */
function rootCallName(callee) {
    let node = callee;
    while (node) {
        if (node.type === "Identifier") {
            return node.name;
        }
        if (node.type === "MemberExpression") {
            node = node.object;
            continue;
        }
        if (node.type === "CallExpression") {
            node = node.callee;
            continue;
        }
        // `it.each`table`(name, fn)` — the outer callee is a tagged template whose
        // `.tag` is the `it.each` member chain; drill into it or the test escapes.
        if (node.type === "TaggedTemplateExpression") {
            node = node.tag;
            continue;
        }
        return null;
    }
    return null;
}
/** A named test declaration: `it`/`test` (any modifier chain) with a string name. */
function isNamedTestCall(node) {
    const root = rootCallName(node.callee);
    if (root !== "it" && root !== "test") {
        return false;
    }
    const first = node.arguments[0];
    if (!first) {
        return false;
    }
    if (first.type === "Literal") {
        return typeof first.value === "string";
    }
    return first.type === "TemplateLiteral";
}
function isLinked(entry, startLine, endLine) {
    if (!entry) {
        return false;
    }
    if (entry.wholeFile) {
        return true;
    }
    for (const line of entry.lines) {
        if (line >= startLine && line <= endLine) {
            return true;
        }
    }
    return false;
}
// With no corpus under specsRoot, every test would flag as unlinked — a
// false-positive storm that means the run started outside the repo root
// (e.g. `eslint apps/floor/` in a subdir). Warn once and skip rather than
// report thousands of misleading errors.
function warnMissingCorpusOnce(specsRoot, roots) {
    if (warnedMissingCorpus.has(specsRoot)) {
        return;
    }
    warnedMissingCorpus.add(specsRoot);
    console.warn(`require-spec-link: no ${roots.join("/")} directory under ${specsRoot} — ` +
        "run eslint from the repo root (or pass options.specsRoot). Skipping the spec-link check.");
}
function testName(sourceCode, first) {
    return first.type === "Literal"
        ? String(first.value)
        : sourceCode.getText(first);
}
function reportUnlinked(context, node, corpus) {
    if (!isNamedTestCall(node)) {
        return;
    }
    const startLine = node.loc.start.line;
    if (isLinked(corpus.entry, startLine, node.loc.end.line)) {
        return;
    }
    context.report({
        node: node.callee,
        messageId: "unlinkedTest",
        data: {
            name: testName(context.sourceCode, node.arguments[0]),
            file: corpus.relPath,
            line: String(startLine),
            roots: corpus.roots.map((root) => `${root}/**/*.md`).join(" or "),
        },
    });
}
export default {
    meta: {
        type: "problem",
        docs: {
            description: "require every test to be linked from a spec or ADR via an inline ([validated by](test.ts#Lline)) link. The spec/adr corpus is read once per process and memoized, so in a long-lived ESLint server (VS Code extension, --watch) a newly added link is not seen until the server restarts; a one-shot `eslint`/CI run always reads fresh.",
        },
        schema: [
            {
                type: "object",
                properties: {
                    specsRoot: { type: "string" },
                    roots: { type: "array", items: { type: "string" } },
                },
                additionalProperties: false,
            },
        ],
        messages: {
            unlinkedTest: "Test {{name}} has no spec link — add an inline ([validated by]({{file}}#L{{line}})) to the statement it validates in a {{roots}} markdown file (or, if this test isn't tied to a spec statement, it may not belong in the traceable suite).",
        },
    },
    create(context) {
        // Match the same predicate `buildLinkIndex` uses to keep validated-by links
        // (isTestFile: .test./.spec./__tests__/…), so a linkable test can't escape
        // the rule on a naming variant.
        if (!isTestFile(toPosix(context.filename))) {
            return {};
        }
        const options = context.options[0] ?? {};
        const specsRoot = options.specsRoot ?? context.cwd;
        const roots = options.roots ?? ["specs", "adrs"];
        if (!corpusExists(specsRoot, roots)) {
            warnMissingCorpusOnce(specsRoot, roots);
            return {};
        }
        const relPath = toPosix(path.relative(specsRoot, context.filename));
        const corpus = {
            entry: getIndex(specsRoot, roots).get(relPath),
            relPath,
            roots,
        };
        return {
            CallExpression: (node) => reportUnlinked(context, node, corpus),
        };
    },
};

/**
 * spec-link-index — reads the org's spec/adr markdown and builds the
 * test-file → linked-lines index the `require-spec-link` rule matches against.
 *
 * The source of truth for a spec↔test link lives INSIDE the spec.md/adr `.md`
 * as an inline trailing parenthetical — `([validated by](path/to/test.ts#L42))`
 * — parsed by the canonical `linksForStatements` (reused here, not re-implemented).
 * Each test link contributes its `#Lline` to that test path's line set; a link
 * with no `#L` anchor marks the whole file linked.
 *
 * Split out of the rule so the pure index (buildLinkIndex) and the filesystem
 * walk (readSpecFiles) are testable without a RuleTester.
 */
import fs from "node:fs";
import path from "node:path";
import { linksForStatements, resolveLinkPath } from "./spec-parsers.mjs";
/** @typedef {{ lines: Set<number>, wholeFile: boolean }} LinkEntry */
export function toPosix(filePath) {
    return filePath.split(path.sep).join("/");
}
/** True when at least one of `dirs` exists under `root`. The rule uses this to
 * tell "no test is linked" from "the corpus was never found" (e.g. eslint run
 * from a subdirectory where `context.cwd` is not the repo root). */
export function corpusExists(root, dirs = ["specs", "adrs"]) {
    return dirs.some((dir) => fs.existsSync(path.join(root, dir)));
}
function testLinksOf(file) {
    return linksForStatements(file.content).flatMap(({ testLinks }) => testLinks.map((link) => ({ link, specPath: file.path })));
}
function entryFor(index, key) {
    const existing = index.get(key);
    if (existing) {
        return existing;
    }
    const created = { lines: new Set(), wholeFile: false };
    index.set(key, created);
    return created;
}
function recordLink(index, { link, specPath }) {
    const entry = entryFor(index, resolveLinkPath(link.path, specPath));
    if (link.line === null) {
        entry.wholeFile = true;
        return;
    }
    entry.lines.add(link.line);
}
/**
 * Fold every test link found across the given markdown files into a
 * `Map<repoRelTestPath, LinkEntry>`. Href paths are resolved to canonical
 * repo-root-relative form via the shared `resolveLinkPath` — the same resolver
 * the graph binder uses — so a `../`-relative href (relative to the spec's own
 * directory, as GitHub renders it) indexes under the test's repo-relative key
 * and matches, instead of a literal `../../apps/x.test.ts` miss.
 *
 * @param {Array<{ path: string, content: string }>} files
 * @returns {Map<string, LinkEntry>}
 */
export function buildLinkIndex(files) {
    const index = new Map();
    files.flatMap(testLinksOf).forEach((found) => recordLink(index, found));
    return index;
}
function readMarkdownUnder(root, base) {
    return fs
        .readdirSync(base, { recursive: true })
        .filter((entry) => entry.endsWith(".md"))
        .map((entry) => {
        const full = path.join(base, entry);
        return {
            path: toPosix(path.relative(root, full)),
            content: fs.readFileSync(full, "utf8"),
        };
    });
}
/**
 * Read every `*.md` under each of `dirs` (relative to `root`), returning
 * `{ path, content }` with a root-relative posix path. Absent dirs are skipped.
 *
 * @param {string} root
 * @param {string[]} [dirs]
 * @returns {Array<{ path: string, content: string }>}
 */
export function readSpecFiles(root, dirs = ["specs", "adrs"]) {
    return dirs
        .map((dir) => path.join(root, dir))
        .filter((base) => fs.existsSync(base))
        .flatMap((base) => readMarkdownUnder(root, base));
}

